import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] counts = new int[10]; // counts[d] = elements containing digit d
        for (int i = 0; i < n; i++) {
            int v = sc.nextInt(), tens = v / 10, ones = v % 10;
            counts[tens]++;
            if (ones != tens) counts[ones]++;
        }
        System.out.println(Arrays.stream(counts).max().getAsInt());
    }
}

package main

import "fmt"

func main() {
	var n int
	fmt.Scan(&n)
	var counts [10]int // counts[d] = elements containing digit d
	for i := 0; i < n; i++ {
		var v int
		fmt.Scan(&v)
		tens, ones := v/10, v%10
		counts[tens]++
		if ones != tens {
			counts[ones]++
		}
	}
	best := 0
	for _, c := range counts {
		best = max(best, c)
	}
	fmt.Println(best)
}
